import React, { useEffect, useState, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { projectsAPI, teamAPI, workersAPI, attendanceAPI, companiesAPI } from '../../services/api';
import { useAuth } from '../../context/AuthContext';
import { usePermissions } from '../../context/PermissionsContext';
import AppLayout from '../../components/layout/AppLayout';
import {
  T, fmtFCFA, fmtN, fmtDate, Card, CardHeader, KPI, StatsGrid,
  ProgressBar, StatusBadge, Badge, DataTable, Btn, Avatar,
  Empty, Alert, Modal, Field, Input, Select, Textarea,
  Spinner, PageContent, PageHeader, SectionTitle, PROJECT_STATUS,
} from '../../components/ui';

// ── Mini helpers ──────────────────────────────────────────────────────────────
function GanttBar({ name, pct, color=T.orange }) {
  return (
    <div style={{ display:'flex', alignItems:'center', gap:12, marginBottom:12 }}>
      <div style={{ width:130, fontSize:12, color:T.text, flexShrink:0, overflow:'hidden', textOverflow:'ellipsis', whiteSpace:'nowrap' }}>{name}</div>
      <div style={{ flex:1, height:18, background:'#F1F3F5', borderRadius:3, overflow:'hidden', position:'relative' }}>
        <div style={{ position:'absolute', left:0, top:0, height:'100%', width:`${pct}%`, background:color, borderRadius:3 }}/>
        <div style={{ position:'absolute', left:'65%', top:0, width:1, height:'100%', background:T.border }}/>
      </div>
      <div style={{ width:32, fontSize:12, color:T.textSub, fontWeight:600, textAlign:'right', flexShrink:0 }}>{pct}%</div>
    </div>
  );
}

// B — Directeur
function DashDirecteur({ projects, stats, offSiteAlerts, loading, navigate }) {
  const delayed = projects.filter(p=>p.is_delayed);
  const totalB = projects.reduce((a,p)=>a+(parseFloat(p.budget)||0),0);
  const totalE = projects.reduce((a,p)=>a+(parseFloat(p.actual_expenses)||0),0);
  const pct = totalB>0 ? Math.round((totalE/totalB)*100) : 0;

  return (
    <>
      {delayed.length>0 && <Alert text={`Retard détecté sur ${delayed.length} projet(s) : ${delayed[0]?.name}`} type="warning"/>}
      {offSiteAlerts.length>0 && <Alert text={`${offSiteAlerts.length} pointage(s) hors-site aujourd'hui`} type="danger"/>}

      <StatsGrid>
        <KPI label="Projets en cours" value={projects.filter(p=>p.status==='en_cours').length} color={T.orange} icon="🏗️"/>
        <KPI label="CA Total prévu" value={fmtN(totalB)} sub="FCFA" color={T.green} icon="💰"/>
        <KPI label="Marge nette" value="18.4%" color={T.green} sub="Objectif : 20%" icon="📈"/>
        <KPI label="Ouvriers pointés" value={stats?.active_workers_now||'—'} sub="Sur tous chantiers" color={T.amber} icon="👷"/>
        <KPI label="Budget consommé" value={`${pct}%`} alert={pct>90} sub={`Reste : ${fmtN(totalB-totalE)} FCFA`}/>
      </StatsGrid>

      <div style={{ display:'grid', gridTemplateColumns:'1.2fr 1fr', gap:18, marginBottom:18 }}>
        <Card>
          <CardHeader title="Phases actives — Planning" badge={`${projects.filter(p=>p.status==='en_cours').length} en cours`} badgeColor={T.orange}/>
          <GanttBar name="Terrassement" pct={78} color={T.orange}/>
          <GanttBar name="Fondations" pct={55} color={T.blue}/>
          <GanttBar name="Structures béton" pct={35} color={T.green}/>
          <GanttBar name="Revêtement" pct={10} color="#D1D9E0"/>
          <div style={{ fontSize:11, color:T.textMuted, marginTop:8 }}>┃ Aujourd'hui (Sem. 11)</div>
        </Card>
        <Card>
          <CardHeader title="Répartition budget"/>
          <div style={{ marginBottom:14 }}>
            <div style={{ display:'flex', justifyContent:'space-between', fontSize:12, color:T.textSub, marginBottom:6 }}>
              <span>Dépensé</span>
              <span style={{ fontWeight:600, color:T.text }}>{fmtFCFA(totalE)} / {fmtFCFA(totalB)}</span>
            </div>
            <ProgressBar pct={pct} color={pct>85?T.red:T.orange} h={10}/>
          </div>
          {[["Main d'œuvre",42,T.orange],['Matériaux',28,T.blue],['Matériels',19,T.green],['Divers',11,T.amber]].map(([l,p,c])=>(
            <div key={l} style={{ display:'flex', alignItems:'center', gap:8, marginBottom:8 }}>
              <div style={{ width:8, height:8, borderRadius:'50%', background:c, flexShrink:0 }}/>
              <span style={{ flex:1, fontSize:12, color:T.text }}>{l}</span>
              <span style={{ fontSize:12, fontWeight:700, color:T.textSub }}>{p}%</span>
            </div>
          ))}
          {/* 🔒 Marge nette — directeur only */}
          <div style={{ marginTop:14, paddingTop:14, borderTop:`1px solid ${T.border}`, background:'#F0FDF4', borderRadius:8, padding:'10px 14px', marginLeft:-14, marginRight:-14, marginBottom:-14 }}>
            <div style={{ fontSize:11, color:'#166534', fontWeight:600, marginBottom:4 }}>🔒 Marge bénéficiaire nette (confidentiel)</div>
            <div style={{ fontSize:22, fontWeight:800, color:T.green }}>18.4%</div>
          </div>
        </Card>
      </div>

      {offSiteAlerts.length>0 && (
        <Card style={{ marginBottom:18, borderColor:`${T.red}30` }}>
          <CardHeader title="Alertes pointage hors-site" badge={offSiteAlerts.length} badgeColor={T.red}/>
          {offSiteAlerts.slice(0,5).map((a,i)=>(
            <div key={i} style={{ display:'flex', gap:12, padding:'9px 12px', background:'#FEF2F2', borderRadius:7, marginBottom:6, fontSize:12 }}>
              <span style={{ color:T.red, fontWeight:600 }}>⛔ {a.worker_name}</span>
              <span style={{ color:T.textSub }}>· {a.distance_from_site}m du chantier · {a.project_name}</span>
            </div>
          ))}
        </Card>
      )}

      <Card>
        <CardHeader title="Mes Projets" action={<Btn to="/projects" size="sm">Voir tous →</Btn>}/>
        {loading ? <div style={{ textAlign:'center', padding:24, color:T.textMuted }}>Chargement…</div> : (
          <div style={{ display:'grid', gridTemplateColumns:'repeat(auto-fill,minmax(260px,1fr))', gap:14, marginTop:8 }}>
            {projects.slice(0,4).map(p=>{
              const pct2=p.progress_pct||0;
              const sc=PROJECT_STATUS[p.status]||PROJECT_STATUS.planifie;
              return (
                <div key={p.id} onClick={()=>navigate(`/projects/${p.id}`)} style={{ border:`1px solid ${T.border}`, borderRadius:10, padding:16, cursor:'pointer', transition:'all .2s', background:'#fff' }}
                  onMouseOver={e=>{e.currentTarget.style.borderColor=T.orange+'80';e.currentTarget.style.transform='translateY(-2px)';}}
                  onMouseOut={e=>{e.currentTarget.style.borderColor=T.border;e.currentTarget.style.transform='none';}}>
                  <div style={{ display:'flex', justifyContent:'space-between', alignItems:'flex-start', marginBottom:8 }}>
                    <div style={{ fontSize:13, fontWeight:600, color:T.text, flex:1, paddingRight:8 }}>{p.name}</div>
                    <StatusBadge status={p.status}/>
                  </div>
