// ── Main ──────────────────────────────────────────────────────────────────────
const PAGE_TITLES = {
  app_owner:'Dashboard Système', admin_entreprise:"Vue d'ensemble Stratégique",
  office_admin:'Dashboard RH & Ressources', chef_projet:"Vue d'ensemble Projet",
  chef_chantier:'Journal de Chantier', chef_equipe:"Mon Équipe — Pointage",
  ingenieur:'Documents & Plans', qhse:'Contrôle Qualité & Sécurité',
  magasinier:'Stocks & Livraisons', comptable:'Budget & Finances', client:'Suivi Projet',
};

export default function DashboardPage() {
  const { user } = useAuth();
  const { role, canViewFinancials } = usePermissions();
  const navigate = useNavigate();

  const [projects,setProjects]=useState([]);
  const [stats,setStats]=useState(null);
  const [team,setTeam]=useState([]);
  const [workers,setWorkers]=useState([]);
  const [companies,setCompanies]=useState([]);
  const [attendance,setAttendance]=useState(null);
  const [offSiteAlerts,setOffSiteAlerts]=useState([]);
  const [loading,setLoading]=useState(true);

  const load = useCallback(async()=>{
    setLoading(true);
    try {
      const calls=[
        projectsAPI.list().catch(()=>({data:[]})),
        projectsAPI.getDashboardStats().catch(()=>({data:null})),
      ];
      if(['app_owner','admin_entreprise','office_admin'].includes(role)) calls.push(teamAPI.list().catch(()=>({data:[]})));
      if(['office_admin','admin_entreprise','app_owner'].includes(role)) calls.push(workersAPI.list().catch(()=>({data:[]})));
      if(role==='app_owner') calls.push(companiesAPI.list().catch(()=>({data:[]})));
      const[pR,sR,...rest]=await Promise.all(calls);
      setProjects(pR.data||[]);setStats(sR.data);
      let i=0;
      if(['app_owner','admin_entreprise','office_admin'].includes(role)){setTeam(rest[i]?.data||[]);i++;}
      if(['office_admin','admin_entreprise','app_owner'].includes(role)){setWorkers(rest[i]?.data||[]);i++;}
      if(role==='app_owner') setCompanies(rest[i]?.data||[]);
    } finally{setLoading(false);}
  },[role]);

  useEffect(()=>{load();},[load]);

  useEffect(()=>{
    if(!['chef_chantier','chef_equipe'].includes(role)||!projects.length) return;
    attendanceAPI.summary(projects[0]?.id).then(r=>setAttendance(r.data)).catch(()=>{});
  },[role,projects]);

  useEffect(()=>{
    if(!['admin_entreprise','app_owner','chef_projet'].includes(role)||!projects.length) return;
    Promise.all(projects.filter(p=>p.status==='en_cours').map(p=>attendanceAPI.alerts(p.id).then(r=>r.data?.alerts||[]).catch(()=>[])))
      .then(r=>setOffSiteAlerts(r.flat()));
  },[role,projects]);

  const pageActions = role==='admin_entreprise' ? (
    <div style={{ display:'flex', gap:10 }}>
      <Btn to="/contracts/upload" size="sm" variant="ghost">📄 Contrat IA</Btn>
      <Btn to="/projects/new" size="sm">+ Nouveau projet</Btn>
    </div>
  ) : role==='chef_chantier' ? <Btn to="/pointage" size="sm" variant="success">📍 Pointage GPS</Btn> : null;

  return (
    <AppLayout projectName={projects[0]?.name}>
      <PageHeader title={PAGE_TITLES[role]||'Dashboard'} subtitle={user?.company?.name||''} actions={pageActions}/>
      <PageContent>
        {loading && ['app_owner'].includes(role) ? (
          <div style={{ display:'flex', justifyContent:'center', padding:60 }}><Spinner color={T.orange}/></div>
        ) : (
          <>
            {role==='app_owner'        && <DashAppOwner    stats={stats} companies={companies} loading={loading}/>}
            {role==='admin_entreprise' && <DashDirecteur   projects={projects} stats={stats} offSiteAlerts={offSiteAlerts} loading={loading} navigate={navigate}/>}
            {role==='office_admin'     && <DashOfficeAdmin team={team} workers={workers} projects={projects} stats={stats} loading={loading}/>}
            {role==='chef_projet'      && <DashChefProjet  projects={projects} loading={loading}/>}
            {role==='chef_chantier'    && <DashChefChantier projects={projects} attendance={attendance} loading={loading} navigate={navigate}/>}
            {['chef_equipe','ingenieur','qhse','magasinier','comptable','client'].includes(role) && (
              <DashSimple projects={projects} role={role} navigate={navigate}/>
            )}
          </>
        )}
      </PageContent>
    </AppLayout>
  );
}
